const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json.body;
  const invoiceNumber = d.invoiceNumber || `INV-${Date.now()}`;
  const clientName = d.clientName || 'Client';
  const clientEmail = d.clientEmail || '';
  const items_list = d.items || [];
  const dueDate = d.dueDate || new Date(Date.now() + 30 * 86400000).toISOString().split('T')[0];
  const currency = d.currency || 'USD';

  let subtotal = 0;
  let tableRows = '';
  for (const lineItem of items_list) {
    const lineTotal = (lineItem.quantity || 1) * (lineItem.price || 0);
    subtotal += lineTotal;
    tableRows += `<tr><td style="padding:8px;border:1px solid #ddd;">${lineItem.description || ''}</td><td style="padding:8px;border:1px solid #ddd;text-align:center;">${lineItem.quantity || 1}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${currency} ${(lineItem.price || 0).toFixed(2)}</td><td style="padding:8px;border:1px solid #ddd;text-align:right;">${currency} ${lineTotal.toFixed(2)}</td></tr>`;
  }

  const tax = d.taxRate ? subtotal * (d.taxRate / 100) : 0;
  const total = subtotal + tax;

  const html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;">
    <div style="background:#2563eb;color:white;padding:20px;text-align:center;">
      <h1 style="margin:0;">INVOICE</h1>
      <p style="margin:5px 0 0;">${invoiceNumber}</p>
    </div>
    <div style="padding:20px;">
      <p><strong>Bill To:</strong> ${clientName}</p>
      <p><strong>Due Date:</strong> ${dueDate}</p>
      <table style="width:100%;border-collapse:collapse;margin:20px 0;">
        <thead><tr style="background:#f3f4f6;"><th style="padding:8px;border:1px solid #ddd;text-align:left;">Description</th><th style="padding:8px;border:1px solid #ddd;">Qty</th><th style="padding:8px;border:1px solid #ddd;text-align:right;">Price</th><th style="padding:8px;border:1px solid #ddd;text-align:right;">Total</th></tr></thead>
        <tbody>${tableRows}</tbody>
      </table>
      <div style="text-align:right;margin-top:10px;">
        <p>Subtotal: ${currency} ${subtotal.toFixed(2)}</p>
        ${tax > 0 ? `<p>Tax (${d.taxRate}%): ${currency} ${tax.toFixed(2)}</p>` : ''}
        <p style="font-size:1.2em;font-weight:bold;">Total: ${currency} ${total.toFixed(2)}</p>
      </div>
    </div>
  </div>`;

  results.push({
    json: {
      clientEmail: clientEmail,
      clientName: clientName,
      invoiceNumber: invoiceNumber,
      htmlBody: html,
      total: total,
      currency: currency,
      dueDate: dueDate,
      sentAt: new Date().toISOString()
    }
  });
}
return results;
